traces.program:
static void A(int x)
{
    Tr.Enter("A");
    Tr.At(1, "A تستلم نسخة من قيمة n.", "x", x);
    x = 10;
    Tr.S("A تغيّر نسختها فقط.", "x", x);
    Tr.Leave();
}
static void B(ref int x)
{
    Tr.Enter("B");
    x = 20;
    Tr.S("مع ref: x في B هو صندوق n نفسه.", "x", x);
    Tr.Leave();
}
static void C(out int x)
{
    Tr.Enter("C");
    x = 30;
    Tr.S("مع out: C تعطي x قيمة، وتعود القيمة إلى n.", "x", x);
    Tr.Leave();
}
static void Main()
{
    Tr.Begin();
    int n = 1;
    Tr.S("صندوق n في Main.", "n", n);
    A(n);
    Tr.S("عدنا من A: n ما زال 1.", "n", n);
    Console.Write(n + " ");
    Tr.S("الطباعة: 1.");
    B(ref n);
    Tr.S("عدنا من B: n صار 20.", "n", n);
    Console.Write(n + " ");
    Tr.S("الطباعة: 20.");
    C(out n);
    Tr.S("عدنا من C: n صار 30.", "n", n);
    Console.Write(n);
    Tr.S("الطباعة: 30.");
    Tr.End();
}

static void G()
{
    Tr.Enter("G");
    Console.Write("G ");
    Tr.S("G فوق F في المكدس: تطبع ثم تنتهي.");
    Tr.Leave();
}
static void F()
{
    Tr.Enter("F");
    Console.Write("F1 ");
    Tr.S("F فوق Main في المكدس.");
    G();
    Tr.S("خرجت G من المكدس: نكمل F بعد سطر الاستدعاء.");
    Console.Write("F2 ");
    Tr.S("F تكمل ثم تنتهي.");
    Tr.Leave();
}
static void Main()
{
    Tr.Begin();
    Console.Write("M1 ");
    Tr.S("Main وحدها في المكدس.");
    F();
    Tr.S("خرجت F: عدنا إلى Main.");
    Console.Write("M2");
    Tr.S("الطباعة الأخيرة.");
    Tr.End();
}
